class Group:
    def __init__(self, members: list[str]) -> None:
        if not members:
            raise ValueError("Group must have at least one member")
        self.members = list(members)
        self._balances: dict[str, float] = {m: 0.0 for m in self.members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if amount <= 0:
            raise ValueError("Amount must be positive")
        if payer not in self._balances:
            raise ValueError(f"Unknown member: {payer}")
        if participants is None:
            participants = list(self.members)
        if not participants:
            raise ValueError("Participants must be non-empty")
        for p in participants:
            if p not in self._balances:
                raise ValueError(f"Unknown member: {p}")

        shares: dict[str, float] = {}
        if len(participants) == 1:
            shares[participants[0]] = round(amount, 2)
        else:
            total_cents = int(round(amount * 100))
            n = len(participants)
            base_cents = total_cents // n
            remainder = total_cents - base_cents * n
            # Leftover cents borne by payer; others get rounded-down amount.
            for p in participants:
                if p == payer:
                    shares[p] = (base_cents + remainder) / 100.0
                else:
                    shares[p] = base_cents / 100.0

        # The payer paid `amount`, so they are owed their share back minus others.
        # Net effect: payer's balance increases by amount minus their own share;
        # each other participant's balance decreases by their share.
        self._balances[payer] = round(self._balances[payer] + amount - shares[payer], 2)
        for p in participants:
            if p != payer:
                self._balances[p] = round(self._balances[p] - shares[p], 2)

    def balances(self) -> dict[str, float]:
        return {m: round(v, 2) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        creditors = []  # (name, amount owed to them)
        debtors = []    # (name, amount they owe)
        for m, v in self._balances.items():
            v = round(v, 2)
            if v >= 1.0:
                creditors.append([m, v])
            elif v <= -1.0:
                debtors.append([m, -v])

        creditors.sort(key=lambda x: -x[1])
        debtors.sort(key=lambda x: -x[1])

        payments: list[tuple[str, str, float]] = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, owe = debtors[i]
            creditor, due = creditors[j]
            pay = round(min(owe, due), 2)
            if pay >= 1.0:
                payments.append((debtor, creditor, pay))
            owe = round(owe - pay, 2)
            due = round(due - pay, 2)
            if owe < 1.0:
                i += 1
            else:
                debtors[i][1] = owe
            if due < 1.0:
                j += 1
            else:
                creditors[j][1] = due

        return payments
